"use server";

import { revalidatePath } from "next/cache";

import { obterReacao } from "@/features/reacoes/consultas";
import { definirReacao } from "@/features/reacoes/gravar";
import { reacaoSchema } from "@/features/reacoes/schema";
import { createClient } from "@/lib/supabase/server";

export type EstadoReacao = { mensagem?: string };

const ERRO_GENERICO = "Não foi possível salvar sua reação agora. Tente de novo.";

/**
 * Marca a reação ao filme; se ela já era a atual, remove (clicar de novo desfaz).
 * Título e gêneros vêm do TMDB no servidor, não do navegador.
 */
export async function alternarReacao(
  _anterior: EstadoReacao,
  formData: FormData,
): Promise<EstadoReacao> {
  const resultado = reacaoSchema.safeParse({
    tmdbId: Number(formData.get("tmdbId")),
    reacao: formData.get("reacao"),
  });
  if (!resultado.success) return { mensagem: ERRO_GENERICO };
  const { tmdbId, reacao } = resultado.data;

  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return { mensagem: "Sua sessão expirou. Entre de novo." };

  const atual = await obterReacao(tmdbId, supabase);
  const gravado = await definirReacao(supabase, user.id, tmdbId, atual === reacao ? null : reacao);
  if (!gravado.ok) {
    return { mensagem: gravado.erro === "filme-nao-encontrado" ? "Filme não encontrado." : ERRO_GENERICO };
  }

  revalidatePath(`/filme/${tmdbId}`);
  revalidatePath("/dashboard");
  return {};
}
import "server-only";

import type { ResultadoDefinir } from "@/features/listas/gravar";
import type { Reacao } from "@/features/reacoes/opcoes";
import type { ClienteSupabase } from "@/lib/supabase/token";
import { obterFilme } from "@/lib/tmdb/filmes";
import type { FilmeDetalhes } from "@/lib/tmdb/tipos";

type BuscarFilme = (id: number) => Promise<FilmeDetalhes | null>;

/** Deixa a reação pedida (`null` apaga). Idempotente; título e gêneros vêm do TMDB. */
export async function definirReacao(
  supabase: ClienteSupabase,
  usuarioId: string,
  tmdbId: number,
  reacao: Reacao | null,
  buscarFilme: BuscarFilme = obterFilme,
): Promise<ResultadoDefinir<Reacao>> {
  const { data: atual, error: erroLeitura } = await supabase
    .from("reacoes")
    .select("reacao, titulo")
    .eq("tmdb_id", tmdbId)
    .maybeSingle();
  if (erroLeitura) {
    console.error("[reacoes] falha ao ler:", erroLeitura.code, erroLeitura.message);
    return { ok: false, erro: "banco" };
  }
  const anterior = atual?.reacao ?? null;

  if (reacao === null) {
    if (atual) {
      const { error } = await supabase.from("reacoes").delete().eq("tmdb_id", tmdbId);
      if (error) {
        console.error("[reacoes] falha ao remover:", error.code, error.message);
        return { ok: false, erro: "banco" };
      }
    }
    return { ok: true, titulo: atual?.titulo ?? null, anterior, atual: null };
  }

  if (atual && anterior === reacao) return { ok: true, titulo: atual.titulo, anterior, atual: reacao };

  let filme: FilmeDetalhes | null;
  try {
    filme = await buscarFilme(tmdbId);
  } catch {
    return { ok: false, erro: "tmdb" };
  }
  if (!filme) return { ok: false, erro: "filme-nao-encontrado" };

  const { error } = await supabase.from("reacoes").upsert({
    usuario_id: usuarioId,
    tmdb_id: tmdbId,
    reacao,
    titulo: filme.titulo,
    generos: filme.generos.map((genero) => genero.id),
  });
  if (error) {
    console.error("[reacoes] falha ao salvar:", error.code, error.message);
    return { ok: false, erro: "banco" };
  }
  return { ok: true, titulo: filme.titulo, anterior, atual: reacao };
}
import "server-only";

import { cache } from "react";

import type { Reacao } from "@/features/reacoes/opcoes";
import type { ReacaoMotor } from "@/features/recomendacao/tipos";
import { createClient } from "@/lib/supabase/server";
import type { ClienteSupabase } from "@/lib/supabase/token";

/** Todas as reações do usuário logado (a RLS limita às dele), no formato do motor. */
export const obterReacoes = cache(async (cliente?: ClienteSupabase): Promise<ReacaoMotor[]> => {
  const supabase = cliente ?? (await createClient());
  const { data, error } = await supabase
    .from("reacoes")
    .select("tmdb_id, reacao, titulo, generos")
    .order("atualizado_em", { ascending: false });

  if (error) {
    console.error("[reacoes] falha ao ler:", error.code, error.message);
    return [];
  }
  return data.map((linha) => ({
    tmdbId: linha.tmdb_id,
    reacao: linha.reacao,
    titulo: linha.titulo,
    generos: linha.generos,
  }));
});

/** Reação do usuário logado a um filme, ou `null`. */
export async function obterReacao(tmdbId: number, cliente?: ClienteSupabase): Promise<Reacao | null> {
  const supabase = cliente ?? (await createClient());
  const { data } = await supabase
    .from("reacoes")
    .select("reacao")
    .eq("tmdb_id", tmdbId)
    .maybeSingle();
  return data?.reacao ?? null;
}
"use client";

import { Play } from "lucide-react";
import Image from "next/image";
import { useState } from "react";

/** Miniatura do YouTube; o player (sem cookies) só é carregado depois do clique. */
export function Trailer({ chave, titulo }: { chave: string; titulo: string }) {
  const [tocando, setTocando] = useState(false);

  return (
    <div className="bg-muted relative aspect-video w-full max-w-3xl overflow-hidden rounded-xl">
      {tocando ? (
        <iframe
          src={`https://www.youtube-nocookie.com/embed/${chave}?autoplay=1`}
          title={`Trailer de ${titulo}`}
          allow="autoplay; encrypted-media; picture-in-picture"
          allowFullScreen
          className="absolute inset-0 size-full"
        />
      ) : (
        <button
          type="button"
          onClick={() => setTocando(true)}
          className="group focus-visible:ring-ring/50 absolute inset-0 outline-none focus-visible:ring-3"
        >
          <Image
            src={`https://i.ytimg.com/vi/${chave}/hqdefault.jpg`}
            alt=""
            fill
            sizes="(min-width: 768px) 768px, 100vw"
            className="object-cover opacity-80 transition-opacity group-hover:opacity-100"
          />
          <span className="bg-primary text-primary-foreground absolute top-1/2 left-1/2 flex -translate-x-1/2 -translate-y-1/2 items-center gap-2 rounded-full px-5 py-3 font-medium shadow-lg">
            <Play className="size-5 fill-current" aria-hidden="true" />
            Assistir trailer
          </span>
        </button>
      )}
    </div>
  );
}
import { ArrowLeft } from "lucide-react";
import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { cache } from "react";

import { Carrossel } from "@/features/dashboard/components/carrossel";
import { CartaoFilme } from "@/features/dashboard/components/cartao-filme";
import { CabecalhoFilme } from "@/features/filme/components/cabecalho-filme";
import { Elenco } from "@/features/filme/components/elenco";
import { OndeAssistir } from "@/features/filme/components/onde-assistir";
import { Trailer } from "@/features/filme/components/trailer";
import { BotoesLista } from "@/features/listas/components/botoes-lista";
import { obterStatusLista } from "@/features/listas/consultas";
import { BotoesReacao } from "@/features/reacoes/components/botoes-reacao";
import { obterReacao } from "@/features/reacoes/consultas";
import { obterFilme } from "@/lib/tmdb/filmes";

/** Só inteiros positivos de até 10 dígitos são IDs válidos do TMDB. */
function lerId(valor: string): number | null {
  if (!/^\d{1,10}$/.test(valor)) return null;
  const id = Number(valor);
  return id > 0 ? id : null;
}

/** Uma busca por renderização, compartilhada entre a página e o título da aba. */
const buscarFilme = cache(async (valor: string) => {
  const id = lerId(valor);
  return id ? obterFilme(id) : null;
});

export async function generateMetadata({ params }: PageProps<"/filme/[id]">): Promise<Metadata> {
  const filme = await buscarFilme((await params).id);
  if (!filme) return { title: "Filme não encontrado" };
  return { title: filme.ano ? `${filme.titulo} (${filme.ano})` : filme.titulo };
}

function Secao({ titulo, children }: { titulo: string; children: React.ReactNode }) {
  return (
    <section className="flex flex-col gap-4">
      <h2 className="text-2xl tracking-tight">{titulo}</h2>
      {children}
    </section>
  );
}

export default async function FilmePage({ params }: PageProps<"/filme/[id]">) {
  const filme = await buscarFilme((await params).id);
  if (!filme) notFound();
  const [reacao, statusLista] = await Promise.all([
    obterReacao(filme.id),
    obterStatusLista(filme.id),
  ]);

  return (
    <div className="mx-auto flex w-full max-w-6xl flex-1 flex-col gap-10 px-4 py-8">
      <Link
        href="/dashboard"
        className="text-muted-foreground hover:text-foreground inline-flex w-fit items-center gap-1 text-sm"
      >
        <ArrowLeft className="size-4" aria-hidden="true" /> Voltar
      </Link>

      <CabecalhoFilme
        filme={filme}
        acoes={
          <>
            <BotoesReacao key={`r-${reacao}`} tmdbId={filme.id} atual={reacao} />
            <BotoesLista key={`l-${statusLista}`} tmdbId={filme.id} atual={statusLista} />
          </>
        }
      />

      <Secao titulo="Sinopse">
        <p className="max-w-3xl leading-relaxed">
          {filme.sinopse || "Sinopse não disponível em português."}
        </p>
        {filme.direcao.length > 0 && (
          <p className="text-muted-foreground text-sm">Direção: {filme.direcao.join(", ")}</p>
        )}
      </Secao>

      {filme.trailerYoutube && (
        <Secao titulo="Trailer">
          <Trailer chave={filme.trailerYoutube} titulo={filme.titulo} />
        </Secao>
      )}

      <Secao titulo="Onde assistir no Brasil">
        <OndeAssistir dados={filme.ondeAssistir} />
      </Secao>

      {filme.elenco.length > 0 && (
        <Secao titulo="Elenco">
          <Elenco pessoas={filme.elenco} />
        </Secao>
      )}

      {filme.parecidos.length > 0 && (
        <section aria-labelledby="titulo-parecidos" className="flex flex-col gap-4">
          <h2 id="titulo-parecidos" className="text-2xl tracking-tight">
            Filmes parecidos
          </h2>
          <Carrossel rotulo="Filmes parecidos">
            {filme.parecidos.map((parecido) => (
              <li key={parecido.id} className="shrink-0 snap-start">
                <CartaoFilme filme={parecido} />
              </li>
            ))}
          </Carrossel>
        </section>
      )}
    </div>
  );
}
export const dynamic = "force-dynamic";

export function GET() {
  return Response.json({
    status: "ok",
    commit: process.env.VERCEL_GIT_COMMIT_SHA ?? null,
  });
}
import { afterEach, describe, expect, it, vi } from "vitest";

import { GET } from "@/app/api/health/route";

describe("GET /api/health", () => {
  afterEach(() => {
    vi.unstubAllEnvs();
  });

  it("devolve o SHA do commit publicado na Vercel", async () => {
    vi.stubEnv("VERCEL_GIT_COMMIT_SHA", "abc1234");

    const resposta = GET();

    expect(resposta.status).toBe(200);
    expect(await resposta.json()).toEqual({ status: "ok", commit: "abc1234" });
  });

  it("devolve commit nulo fora da Vercel", async () => {
    vi.stubEnv("VERCEL_GIT_COMMIT_SHA", undefined);

    expect(await GET().json()).toEqual({ status: "ok", commit: null });
  });
});

