import type { NomeEvento, Pergunta } from "@/features/metricas/eventos";

/** Ordem e descrição dos eventos na página de métricas. */
export const ROTULOS_EVENTO: Record<NomeEvento, string> = {
  wizard_iniciado: "Abriu o wizard",
  wizard_concluido: "Chegou à recomendação",
  wizard_troca: "Pediu outra sugestão",
  wizard_escolheu: "Clicou “Vou ver esse!”",
  wizard_abandonado: "Saiu sem escolher",
  como_foi_exibido: "Viu o “Como foi?”",
  como_foi_respondido: "Respondeu o “Como foi?”",
  trailer_aberto: "Abriu um trailer",
};

export const ROTULOS_PERGUNTA: Record<Pergunta, string> = {
  humor: "Como está se sentindo",
  experiencia: "Que experiência quer",
  companhia: "Com quem vai assistir",
};

/** Rótulo de cada resposta do wizard, pelo slug gravado (pedido do cliente, 3.2). */
export const ROTULOS_CLIMA: Record<string, string> = {
  cansado: "Cansado",
  animado: "Animado",
  "pra-baixo": "Pra baixo",
  nostalgico: "Nostálgico",
  ansioso: "Ansioso",
  "de-boa": "De boa",
  rir: "Rir",
  emocionar: "Me emocionar",
  susto: "Levar susto",
  tenso: "Ficar tenso",
  pensar: "Pensar",
  distrair: "Só me distrair",
  sozinho: "Sozinho",
  "a-dois": "A dois",
  familia: "Família com crianças",
  amigos: "Amigos",
};

import "server-only";

import type { ClienteSupabase } from "@/lib/supabase/token";

export type TotalEvento = { nome: string; total: number; pessoas: number; semEquipe: number };
export type TotalClima = { pergunta: string; resposta: string; total: number };
export type Metricas = { eventos: TotalEvento[]; climas: TotalClima[] };

/** Código do Postgres para "sem permissão": quem não está em `equipe_metricas`. */
const SEM_PERMISSAO = "42501";

/**
 * Totais de uso para a página `/metricas`, ou `null` se a pessoa não é da equipe.
 * As funções do banco fazem a checagem; outros erros sobem para a página de erro.
 */
export async function obterMetricas(supabase: ClienteSupabase): Promise<Metricas | null> {
  const [eventos, climas] = await Promise.all([
    supabase.rpc("metricas_eventos"),
    supabase.rpc("metricas_climas"),
  ]);
  const erro = eventos.error ?? climas.error;
  if (erro) {
    if (erro.code === SEM_PERMISSAO) return null;
    throw new Error(`[metricas] falha ao ler os totais: ${erro.code} ${erro.message}`);
  }
  return {
    eventos: (eventos.data ?? []).map(({ sem_equipe, ...linha }) => ({ ...linha, semEquipe: sem_equipe })),
    climas: climas.data ?? [],
  };
}

import type { Metricas } from "@/features/metricas/consultas";
import { CLIMAS, type NomeEvento, type Pergunta } from "@/features/metricas/eventos";
import { ROTULOS_CLIMA, ROTULOS_EVENTO, ROTULOS_PERGUNTA } from "@/features/metricas/rotulos";

const celula = "border-border border-b px-3 py-2";
const numero = `${celula} text-right tabular-nums`;

/** Todos os eventos da lista, na ordem dos rótulos, com zero para os que ainda não ocorreram. */
function TabelaEventos({ eventos }: { eventos: Metricas["eventos"] }) {
  const porNome = new Map(eventos.map((evento) => [evento.nome, evento]));
  return (
    <table className="w-full text-sm">
      <caption className="sr-only">Eventos de uso</caption>
      <thead className="text-muted-foreground text-left">
        <tr>
          <th className={celula}>Evento</th>
          <th className={`${celula} text-right`}>Total</th>
          <th className={`${celula} text-right`}>Pessoas</th>
          <th className={`${celula} text-right`}>Sem a equipe</th>
        </tr>
      </thead>
      <tbody>
        {(Object.keys(ROTULOS_EVENTO) as NomeEvento[]).map((nome) => {
          const linha = porNome.get(nome);
          return (
            <tr key={nome}>
              <th scope="row" className={`${celula} text-left font-normal`}>
                {ROTULOS_EVENTO[nome]} <code className="text-muted-foreground text-xs">{nome}</code>
              </th>
              <td className={numero}>{linha?.total ?? 0}</td>
              <td className={numero}>{linha?.pessoas ?? 0}</td>
              <td className={numero}>{linha?.semEquipe ?? 0}</td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );
}

/** Uma tabela por pergunta do wizard, da resposta mais escolhida para a menos. */
function TabelaClima({ pergunta, climas }: { pergunta: Pergunta; climas: Metricas["climas"] }) {
  const total = (resposta: string) =>
    climas.find((clima) => clima.pergunta === pergunta && clima.resposta === resposta)?.total ?? 0;
  const respostas = [...CLIMAS[pergunta]].sort((a, b) => total(b) - total(a));
  return (
    <table className="w-full text-sm">
      <caption className="mb-2 text-left font-medium">{ROTULOS_PERGUNTA[pergunta]}</caption>
      <tbody>
        {respostas.map((resposta) => (
          <tr key={resposta}>
            <th scope="row" className={`${celula} text-left font-normal`}>
              {ROTULOS_CLIMA[resposta]}
            </th>
            <td className={numero}>{total(resposta)}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

export function TabelaMetricas({ metricas }: { metricas: Metricas }) {
  return (
    <div className="flex flex-col gap-10">
      <section aria-labelledby="titulo-eventos" className="flex flex-col gap-3">
        <h2 id="titulo-eventos" className="text-2xl tracking-tight">
          Eventos
        </h2>
        <TabelaEventos eventos={metricas.eventos} />
      </section>
      <section aria-labelledby="titulo-climas" className="flex flex-col gap-3">
        <h2 id="titulo-climas" className="text-2xl tracking-tight">
          Climas do wizard
        </h2>
        <p className="text-muted-foreground text-sm">
          Contados sem vínculo com a pessoa, por isso não há separação da equipe.
        </p>
        <div className="grid gap-6 sm:grid-cols-3">
          {(Object.keys(CLIMAS) as Pergunta[]).map((pergunta) => (
            <TabelaClima key={pergunta} pergunta={pergunta} climas={metricas.climas} />
          ))}
        </div>
      </section>
    </div>
  );
}

import type { Metadata } from "next";
import { notFound } from "next/navigation";

import { TabelaMetricas } from "@/features/metricas/components/tabela-metricas";
import { obterMetricas } from "@/features/metricas/consultas";
import { createClient } from "@/lib/supabase/server";

export const metadata: Metadata = { title: "Métricas de uso", robots: { index: false } };

/** Totais de uso, só para quem está em `equipe_metricas` (SPEC/2026-11-18-metricas.md). */
export default async function MetricasPage() {
  const metricas = await obterMetricas(await createClient());
  if (!metricas) notFound();

  return (
    <div className="mx-auto flex w-full max-w-4xl flex-1 flex-col gap-8 px-4 py-10">
      <header className="flex flex-col gap-2">
        <h1 className="text-4xl tracking-tight">Métricas de uso</h1>
        <p className="text-muted-foreground">
          Totais desde o início da medição. A coluna “Sem a equipe” exclui a dupla e os clientes.
        </p>
      </header>
      <TabelaMetricas metricas={metricas} />
    </div>
  );
}

